{"updateMode":"clearAllTasks","tasksRaw":"[
  {
    "name": "Locate and Collect Recent Ableton Error Logs",
    "description": "Search system directories for recent Ableton application logs, identify log file locations, and extract relevant error logs from the past 7-14 days. Include both crash logs and regular error logs.",
    "implementationGuide": "1. Check common log locations: %APPDATA%\\Ableton\\, %LOCALAPPDATA%\\Ableton\\, and system logs\n2. Use file system tools to list recent log files\n3. Extract log content using text processing tools\n4. Filter for crash-related entries (error codes, crash timestamps)\n5. Save collected logs to a dedicated analysis directory",
    "notes": "Ableton typically stores logs in AppData folders. Look for files with names like 'log.txt', 'error.log', or crash dumps. Focus on the most recent 7-14 days.",
    "dependencies": [],
    "relatedFiles": [
      {
        "path": "txt/log_today.txt",
        "type": "REFERENCE",
        "description": "Sample log file for reference",
        "lineStart": 1,
        "lineEnd": 100
      },
      {
        "path": "txt/log_yesterday.txt",
        "type": "REFERENCE",
        "description": "Previous day's log file for comparison",
        "lineStart": 1,
        "lineEnd": 100
      }
    ],
    "verificationCriteria": "Successfully located and collected at least 3-5 recent log files from Ableton application. Collected logs contain error messages, timestamps, and crash-related entries from the past 7-14 days."
  },
  {
    "name": "Parse and Extract Error Patterns from Logs",
    "description": "Parse collected log files to extract error messages, error codes, timestamps, and relevant context. Identify crash patterns and categorize different types of errors.",
    "implementationGuide": "1. Read log files and extract error entries using regex patterns\n2. Parse timestamps and correlate with crash events\n3. Extract error codes, error messages, and stack traces\n4. Categorize errors by type (memory, file I/O, plugin, etc.)\n5. Create structured data format for analysis",
    "notes": "Use regular expressions to identify common error patterns like 'error code', 'crash', 'exception', 'segmentation fault', etc. Focus on entries with timestamps matching crash times.",
    "dependencies": ["Locate and Collect Recent Ableton Error Logs"],
    "relatedFiles": [
      {
        "path": "code/log_analysis.py",
        "type": "TO_MODIFY",
        "description": "Log parsing script to be developed",
        "lineStart": 1,
        "lineEnd": 200
      }
    ],
    "verificationCriteria": "Successfully parsed all collected log files and extracted at least 20-30 error entries with timestamps, error codes, and context. Created structured data showing error patterns and categories."
  },
  {
    "name": "Identify Common Crash Patterns and Root Causes",
    "description": "Analyze extracted error patterns to identify common crash triggers, recurring issues, and potential root causes. Correlate errors with specific actions, file types, or system conditions.",
    "implementationGuide": "1. Group errors by type and frequency\n2. Identify patterns in crash triggers (specific plugins, file operations, memory usage)\n3. Cross-reference with Ableton documentation and known issues\n4. Analyze system resource usage patterns during crashes\n5. Create root cause hypothesis based on evidence",
    "notes": "Look for patterns like: specific plugin crashes, memory leaks, file corruption issues, driver conflicts, or system resource exhaustion. Correlate crash times with system events.",
    "dependencies": ["Parse and Extract Error Patterns from Logs"],
    "relatedFiles": [
      {
        "path": "code/log_analysis.py",
        "type": "TO_MODIFY",
        "description": "Update analysis script with pattern detection",
        "lineStart": 201,
        "lineEnd": 400
      }
    ],
    "verificationCriteria": "Identified 3-5 common crash patterns with supporting evidence. Established clear root cause hypotheses with correlation between error patterns and crash triggers."
  },
  {
    "name": "Verify Root Cause with Additional Investigation",
    "description": "Conduct additional investigation to verify root cause hypotheses, including checking system resources, dependencies, and known Ableton issues. Gather evidence to confirm or refute initial hypotheses.",
    "implementationGuide": "1. Check system resource usage during crash times\n2. Review system logs for related errors\n3. Check for known Ableton issues in official documentation\n4. Test suspected triggers in controlled environment\n5. Gather evidence to validate or refine root cause hypotheses",
    "notes": "Use system monitoring tools to check CPU, memory, disk I/O during crash times. Check Windows Event Viewer or macOS Console for related system errors. Consult Ableton forums and documentation.",
    "dependencies": ["Identify Common Crash Patterns and Root Causes"],
    "relatedFiles": [
      {
        "path": "txt/log_today.txt",
        "type": "REFERENCE",
        "description": "Cross-reference with recent logs",
        "lineStart": 1,
        "lineEnd": 100
      }
    ],
    "verificationCriteria": "Verified root cause hypotheses with at least 2-3 pieces of supporting evidence. Confirmed or refined root cause with clear documentation of investigation process and findings."
  },
  {
    "name": "Propose Specific Fixes and Troubleshooting Solutions",
    "description": "Based on verified root cause, propose specific fixes including immediate solutions, preventive measures, and long-term recommendations. Provide step-by-step troubleshooting guide.",
    "implementationGuide": "1. Develop immediate fixes for the identified crash cause\n2. Create preventive measures to avoid recurrence\n3. Provide step-by-step troubleshooting guide\n4. Recommend system configuration changes if needed\n5. Document all fixes with clear implementation steps",
    "notes": "Fixes should be practical and actionable. Include both quick fixes (restart, disable plugins) and comprehensive solutions (update drivers, modify settings). Provide clear success criteria.",
    "dependencies": ["Verify Root Cause with Additional Investigation"],
    "relatedFiles": [
      {
        "path": "markdown/work.md",
        "type": "TO_MODIFY",
        "description": "Document findings and recommendations",
        "lineStart": 1,
        "lineEnd": 500
      }
    ],
    "verificationCriteria": "Proposed 3-5 specific fixes with clear implementation steps. Each fix includes success criteria, potential risks, and preventive measures. Troubleshooting guide is comprehensive and easy to follow."
  },
  {
    "name": "Create Final Report and Documentation",
    "description": "Compile all findings, analysis results, and recommendations into a comprehensive report. Include executive summary, detailed analysis, and actionable recommendations for Ableton users.",
    "implementationGuide": "1. Create executive summary of findings\n2. Document root cause analysis process and results\n3. Include all error patterns and evidence\n4. Provide step-by-step fix implementation guide\n5. Add troubleshooting checklist and preventive measures\n6. Format as readable markdown document",
    "notes": "Structure the report with clear sections: Executive Summary, Methodology, Findings, Root Cause Analysis, Recommendations, and Troubleshooting Guide. Use bullet points and code blocks for clarity.",
    "dependencies": ["Propose Specific Fixes and Troubleshooting Solutions"],
    "relatedFiles": [
      {
        "path": "markdown/work.md",
        "type": "TO_MODIFY",
        "description": "Final report document",
        "lineStart": 501,
        "lineEnd": 1000
      }
    ],
    "verificationCriteria": "Created comprehensive report with all required sections. Report is well-structured, easy to read, and contains actionable recommendations. All findings and fixes are clearly documented."
  }
]"}

